import AxeBuilder from "@axe-core/playwright";
import { expect, test, type BrowserContext, type Page } from "@playwright/test";
import { withDb } from "./db";
import { ADMIN } from "./helpers";

/**
 * Phase 5 acceptance: a stranger signs up, submits a bKash proof, the platform approves it, and their store goes from trial to Pro.
 * Also: the unpaid lifecycle (grace, read-only, locked) and the way back, platform suspension, and the brand-review flag.
 * Four apps run together: the marketing site (3002), the store admin (3001), the storefront (3000) and the super admin (3003).
 */
const MKT = "http://localhost:3002";
const PLAT = "http://localhost:3003";
const CRON = { Authorization: "Bearer e2e-cron-secret-0123456789" };
const stamp = Date.now().toString(36);
const storeUrl = (sub: string) => `http://${sub}.localhost:3000`;
let n = 0;
const unique = (p: string) => `${p}${stamp}${++n}`;
const trx = () => `E5${Date.now().toString(36).toUpperCase()}${++n}`.slice(0, 11).padEnd(9, "Q");

async function actOnAdmin(context: BrowserContext, sub: string) {
  await context.addCookies([{ name: "dev_tenant", value: sub, url: ADMIN }]);
}
async function actOnPlatform(context: BrowserContext, who: "owner" | "finance" | "lead" | "support") {
  await context.addCookies([{ name: "dev_platform_user", value: `${who}@biztrackbd.example`, url: PLAT }]);
}

/** Fills the wizard from the first step to the last and presses Create. Returns the address and owner it used. */
async function signUp(page: Page, o: { storeName: string; sub?: string; plan?: "STARTER" | "PRO" | "BUSINESS" }) {
  const sub = o.sub ?? unique("e2e");
  const email = `${sub}@example.test`;
  await page.goto(`${MKT}/start`);
  await expect(page.getByTestId("wizard")).toBeVisible();
  await page.getByTestId("f-ownerName").fill("Nusrat Jahan");
  await page.getByTestId("f-email").fill(email);
  await page.getByTestId("f-phone").fill(`01${3 + (n % 7)}${String(Date.now() % 100_000_000).padStart(8, "0")}`);
  await page.getByTestId("next").click();
  await page.getByTestId("f-storeName").fill(o.storeName);
  await page.getByTestId("next").click();
  await page.getByTestId("f-subdomain").fill(sub);
  await expect(page.getByTestId("address-status")).toContainText("is available");
  await page.getByTestId("next").click();
  if (o.plan) await page.getByTestId(`pick-${o.plan}`).click();
  await page.getByTestId("next").click();
  await expect(page.getByTestId("step-create")).toContainText(o.storeName);
  await page.getByTestId("create").click();
  await expect(page.getByTestId("done")).toBeVisible({ timeout: 30_000 });
  return { sub, email };
}

/** Sets how long ago the store's paid time (or trial) ran out, then runs the daily sweep. */
async function lapse(request: Parameters<Parameters<typeof test>[2]>[0]["request"], sub: string, days: number) {
  await withDb(async (c) => {
    const d = `timezone('utc', now()) - interval '${days} days'`;
    await c.query(`UPDATE "Tenant" SET "trialEndsAt" = ${d} WHERE subdomain = $1`, [sub]);
    await c.query(`UPDATE "Subscription" SET "currentPeriodEnd" = ${d} WHERE "tenantId" = (SELECT id FROM "Tenant" WHERE subdomain = $1)`, [sub]);
  });
  const r = await request.post(`${PLAT}/api/cron/billing`, { headers: CRON });
  expect(r.status()).toBe(200);
}

async function pay(page: Page, plan: "STARTER" | "PRO" | "BUSINESS", amountText: string) {
  await page.goto(`${ADMIN}/billing`);
  await page.getByTestId(`plan-${plan}`).click();
  await expect(page.getByTestId("pay-instructions")).toContainText(amountText);
  await expect(page.getByTestId("pay-instructions")).toContainText("01800000000");
  await page.getByLabel("The number you sent from").fill("01712345678");
  // Enter submits the form: a click can land under the phone's bottom tab bar while the page is still settling.
  await page.getByLabel("Transaction ID (TrxID)").fill(trx());
  await page.getByLabel("Transaction ID (TrxID)").press("Enter");
  await expect(page.getByTestId("proof-sent")).toBeVisible();
  await expect(page.getByTestId("pending-proof")).toBeVisible();
}

async function approveFirst(page: Page, sub: string) {
  await page.goto(`${PLAT}/payments`);
  const card = page.getByTestId("payment-card").filter({ hasText: sub });
  await expect(card).toBeVisible();
  await card.getByRole("button", { name: /Approve and switch the plan on/ }).click();
  await expect(page.getByText("Approved. The plan is live.")).toBeVisible();
}

async function waitForStore(page: Page, sub: string, status: number) {
  await expect.poll(async () => (await page.goto(storeUrl(sub)))?.status(), { timeout: 40_000, intervals: [1000, 2000] }).toBe(status);
}

test.describe.serial("signup, billing and the super admin", () => {
  let sub = "";
  let email = "";
  const storeName = `E2E Threads ${stamp}`;

  test("a stranger opens a store from the marketing site, step by step, with live checks", async ({ page }) => {
    await page.goto(MKT);
    await page.getByTestId("hero-cta").click();
    await expect(page).toHaveURL(/\/start/);
    // Each step refuses what it cannot accept, in plain words.
    await page.getByTestId("next").click();
    await expect(page.getByTestId("step-problem")).toContainText("Enter your name");
    await page.getByTestId("f-ownerName").fill("Nusrat Jahan");
    await page.getByTestId("f-email").fill("not-an-email");
    await page.getByTestId("next").click();
    await expect(page.getByTestId("step-problem")).toContainText("valid email");
    await page.getByTestId("f-email").fill(`probe${stamp}@example.test`);
    await page.getByTestId("f-phone").fill("12345");
    await page.getByTestId("next").click();
    await expect(page.getByTestId("step-problem")).toContainText("valid mobile number");
    await page.getByTestId("f-phone").fill("01712345678");
    await page.getByTestId("next").click();
    await page.getByTestId("f-storeName").fill(storeName);
    await page.getByTestId("next").click();
    // The address is suggested from the name. A taken one and a reserved one are refused as you type.
    await expect(page.getByTestId("f-subdomain")).toHaveValue(/^e2e-threads-/);
    await page.getByTestId("f-subdomain").fill("rongdhonu");
    await expect(page.getByTestId("address-status")).toContainText("already taken");
    await page.getByTestId("next").click();
    await expect(page.getByTestId("step-problem")).toContainText("already taken");
    await page.getByTestId("f-subdomain").fill("admin");
    await expect(page.getByTestId("address-status")).toContainText("kept for BizTrackBD");
    // Back keeps what was typed.
    await page.getByRole("button", { name: "Back" }).click();
    await expect(page.getByTestId("f-storeName")).toHaveValue(storeName);
  });

  test("it creates the store and shows where it lives", async ({ page }) => {
    const r = await signUp(page, { storeName, plan: "STARTER" });
    sub = r.sub;
    email = r.email;
    await expect(page.getByTestId("store-url")).toContainText(`${sub}.localhost:3000`);
    await expect(page.getByTestId("open-store")).toHaveAttribute("href", storeUrl(sub));
    await expect(page.getByTestId("done")).toContainText("free trial runs until");
  });

  test("the new store is already live with sample products", async ({ page }) => {
    const res = await page.goto(storeUrl(sub));
    expect(res?.status()).toBe(200);
    await expect(page.getByText("Sample cotton panjabi").first()).toBeVisible();
  });

  test("the owner sees a 14-day trial and no warning", async ({ context, page }) => {
    await actOnAdmin(context, sub);
    await page.goto(`${ADMIN}/billing`);
    await expect(page.getByTestId("plan-status-text")).toContainText("Free trial, 14 days left");
    await expect(page.getByTestId("access-state")).toHaveText("Free trial");
    await expect(page.getByTestId("billing-banner")).toHaveCount(0);
    await expect(page.getByTestId("plan-status")).toContainText("Starter plan");
    // The sample products are there to look at.
    await page.goto(`${ADMIN}/products`);
    await expect(page.getByText("Sample linen shirt").filter({ visible: true }).first()).toBeVisible();
  });

  test("the owner sends a bKash payment for Pro: the TrxID must look right, and the price is the plan's", async ({ context, page }) => {
    await actOnAdmin(context, sub);
    await page.goto(`${ADMIN}/billing`);
    await page.getByTestId("plan-PRO").click();
    await page.getByLabel("The number you sent from").fill("01712345678");
    await page.getByLabel("Transaction ID (TrxID)").fill("abc-1234");
    await page.getByRole("button", { name: /Check my payment/ }).click();
    await expect(page.getByTestId("pay-error")).toContainText("does not look right");
    await pay(page, "PRO", "৳ 1,499");
    await expect(page.getByTestId("proofs-table")).toContainText("Waiting to be checked");
  });

  test("finance checks the payment and approves it; the store goes from trial to Pro", async ({ context, page }) => {
    await actOnPlatform(context, "finance");
    await page.goto(`${PLAT}/payments`);
    const card = page.getByTestId("payment-card").filter({ hasText: sub });
    await expect(card).toContainText("Pro · 1 month");
    await expect(card.getByTestId("amount")).toHaveText("৳ 1,499");
    await expect(card.getByTestId("trx")).toHaveText(/^E5/);
    await card.getByRole("button", { name: /Approve and switch the plan on/ }).click();
    await expect(page.getByText("Approved. The plan is live.")).toBeVisible();
    await expect(page.getByTestId("payment-card").filter({ hasText: sub })).toHaveCount(0);

    await page.goto(`${PLAT}/tenants?q=${sub}`);
    const row = page.getByTestId("tenant-row").filter({ hasText: storeName });
    await expect(row).toContainText("Pro");
    await expect(row).toContainText("Active");
    await page.goto(`${PLAT}/`);
    await expect(page.getByTestId("mrr")).not.toHaveText("৳ 0");
    await expect(page.getByTestId("paying")).not.toHaveText("0");
  });

  test("the owner now sees an active Pro plan with the payment approved", async ({ context, page }) => {
    await actOnAdmin(context, sub);
    await page.goto(`${ADMIN}/billing`);
    await expect(page.getByTestId("plan-status")).toContainText("Pro plan");
    await expect(page.getByTestId("access-state")).toHaveText("Active");
    await expect(page.getByTestId("plan-status-text")).toContainText("Active until");
    await expect(page.getByTestId("proofs-table")).toContainText("Approved");
    await expect(page.getByTestId("proofs-table")).toContainText("Paid until");
  });

  test("support staff can look at stores but cannot approve payments or edit plans", async ({ context, page }) => {
    await actOnPlatform(context, "support");
    await page.goto(`${PLAT}/payments`);
    await expect(page).toHaveURL(/\/no-access/);
    await page.goto(`${PLAT}/plans`);
    await expect(page).toHaveURL(/\/no-access/);
    await page.goto(`${PLAT}/tenants?q=${sub}`);
    await page.getByTestId("tenant-row").filter({ hasText: storeName }).getByRole("link").first().click();
    await expect(page.getByTestId("tenant-title")).toHaveText(storeName);
    await expect(page.getByRole("button", { name: "Suspend store" })).toHaveCount(0);
    await expect(page.getByRole("button", { name: "Change plan" })).toHaveCount(0);
    await expect(page.getByTestId("usage-card")).toContainText("Products");
  });

  test("when the plan runs out: grace, then read-only and offline, then locked, and paying brings it all back", async ({ context, page, request }) => {
    await actOnAdmin(context, sub);
    // Day 2 overdue: everything still works, a banner asks for payment.
    await lapse(request, sub, 1.5);
    await page.goto(`${ADMIN}/`);
    await expect(page.getByTestId("billing-banner")).toContainText("plan has run out");
    await page.goto(`${ADMIN}/settings/store`);
    await expect(page.locator("main form button[type=submit]").first()).toBeEnabled();
    expect((await page.goto(storeUrl(sub)))?.status()).toBe(200);

    // Day 5: the storefront goes offline and every admin form is switched off, except paying.
    await lapse(request, sub, 5);
    await page.goto(`${ADMIN}/`);
    await expect(page.getByTestId("billing-banner")).toContainText("read-only");
    await page.goto(`${ADMIN}/settings/store`);
    await expect(page.getByTestId("read-only-guard")).toBeVisible();
    await expect(page.locator("main form button[type=submit]").first()).toBeDisabled();
    await page.goto(`${ADMIN}/orders`); // looking still works
    await expect(page.getByRole("heading", { name: "Orders" })).toBeVisible();
    await waitForStore(page, sub, 503);

    // Day 20: locked. Only the billing screen opens.
    await lapse(request, sub, 20);
    await page.goto(`${ADMIN}/orders`);
    await expect(page).toHaveURL(/\/locked/);
    await expect(page.getByTestId("locked")).toContainText("locked");
    await page.getByRole("link", { name: "See plans and pay" }).click();
    await expect(page).toHaveURL(/\/billing/);
    await expect(page.getByTestId("access-state")).toHaveText("Locked");

    // Paying works from here, and one approval brings the store back.
    await pay(page, "PRO", "৳ 1,499");
    await actOnPlatform(context, "finance");
    await approveFirst(page, sub);
    await page.goto(`${ADMIN}/orders`);
    await expect(page.getByRole("heading", { name: "Orders" })).toBeVisible();
    await page.goto(`${ADMIN}/billing`);
    await expect(page.getByTestId("access-state")).toHaveText("Active");
    await waitForStore(page, sub, 200);
  });

  test("the platform can switch a store off, with a reason the owner sees, and back on", async ({ context, page }) => {
    await actOnPlatform(context, "lead");
    await page.goto(`${PLAT}/tenants?q=${sub}`);
    await page.getByTestId("tenant-row").filter({ hasText: storeName }).getByRole("link").first().click();
    await page.getByLabel("Reason").fill("Customers report fake products");
    await page.getByRole("button", { name: "Suspend store" }).click();
    await expect(page.getByText("Store switched off.")).toBeVisible();
    await expect(page.getByTestId("suspended-note")).toContainText("fake products");

    await actOnAdmin(context, sub);
    await page.goto(`${ADMIN}/orders`);
    await expect(page.getByTestId("locked")).toContainText("switched off");
    await page.goto(`${PLAT}/tenants?q=${sub}`);
    await page.getByTestId("tenant-row").filter({ hasText: storeName }).getByRole("link").first().click();
    await page.getByRole("button", { name: "Switch back on" }).click();
    await expect(page.getByText("Store switched back on.")).toBeVisible();
    await page.goto(`${ADMIN}/orders`);
    await expect(page.getByRole("heading", { name: "Orders" })).toBeVisible();
  });

  test("a store named after a well-known brand is flagged for a person to look at", async ({ context, page }) => {
    const flagged = await signUp(page, { storeName: `Daraz Mirpur Outlet ${stamp}` });
    await expect(page.getByTestId("done")).toContainText("a person will check it");
    await actOnPlatform(context, "lead");
    await page.goto(`${PLAT}/tenants?filter=flagged`);
    const row = page.getByTestId("tenant-row").filter({ hasText: flagged.sub });
    await expect(row).toContainText("Flagged");
    await row.getByRole("link").first().click();
    await page.getByLabel("Review note").fill("Has permission, letter seen");
    await page.getByRole("button", { name: "Approve", exact: true }).click();
    await expect(page.getByText("Flagged store approved.")).toBeVisible();
    await page.goto(`${PLAT}/tenants?filter=flagged`);
    await expect(page.getByTestId("tenant-row").filter({ hasText: flagged.sub })).toHaveCount(0);
  });

  test("the daily sweep refuses anyone without the secret", async ({ request }) => {
    expect((await request.post(`${PLAT}/api/cron/billing`)).status()).toBe(401);
    expect((await request.post(`${PLAT}/api/cron/billing`, { headers: { Authorization: "Bearer wrong-wrong-wrong-wrong" } })).status()).toBe(401);
  });

  test("the plans page edits a price, and the new price shows on the marketing site", async ({ context, page }) => {
    await actOnPlatform(context, "owner");
    await page.goto(`${PLAT}/plans`);
    const form = page.getByTestId("plan-STARTER");
    await form.getByLabel("Monthly price (৳)").fill("749");
    await form.getByRole("button", { name: "Save Starter" }).click();
    await expect(page.getByText("STARTER saved.")).toBeVisible();
    await page.goto(`${MKT}/pricing`);
    await expect(page.getByTestId("plan-STARTER")).toContainText("৳ 749");
    await page.goto(`${PLAT}/plans`);
    await page.getByTestId("plan-STARTER").getByLabel("Monthly price (৳)").fill("699");
    await page.getByTestId("plan-STARTER").getByRole("button", { name: "Save Starter" }).click();
    await expect(page.getByText("STARTER saved.")).toBeVisible();
    await page.goto(`${PLAT}/audit?action=PLAN_EDITED`);
    await expect(page.getByTestId("audit-table")).toContainText("PLAN_EDITED");
  });
});

test.describe("pricing and templates pages", () => {
  test("pricing shows every public plan from the Plan table", async ({ page }) => {
    await page.goto(`${MKT}/pricing`);
    for (const [tier, price] of [["STARTER", "৳ 699"], ["PRO", "৳ 1,499"], ["BUSINESS", "৳ 3,499"]]) await expect(page.getByTestId(`plan-${tier}`)).toContainText(price!);
    await expect(page.getByTestId("plan-PRO")).toContainText("Book Steadfast, Pathao and RedX");
    await expect(page.getByTestId("plan-STARTER")).not.toContainText("Your own domain");
    await page.getByTestId("plan-PRO").getByRole("link", { name: /Start free with Pro/ }).click();
    await expect(page).toHaveURL(/plan=PRO/);
  });

  test("templates shows every storefront template as ready", async ({ page }) => {
    await page.goto(`${MKT}/templates`);
    for (const id of ["kapor", "gadgetstudio", "mini-bunny", "axionwear", "bindu"]) {
      await expect(page.getByTestId(`theme-${id}`)).toContainText("Ready");
      await expect(page.getByTestId(`theme-${id}`).getByRole("link", { name: "Use this template" })).toHaveCount(1);
    }
  });
});

const SCREENS: { name: string; url: string; as?: "owner" }[] = [
  { name: "marketing home", url: `${MKT}/` },
  { name: "pricing", url: `${MKT}/pricing` },
  { name: "templates", url: `${MKT}/templates` },
  { name: "signup", url: `${MKT}/start` },
  { name: "signup done", url: `${MKT}/start/done?store=example-shop&name=Example&ends=2026-12-01T00:00:00Z` },
  { name: "super admin overview", url: `${PLAT}/`, as: "owner" },
  { name: "super admin stores", url: `${PLAT}/tenants`, as: "owner" },
  { name: "super admin payments", url: `${PLAT}/payments`, as: "owner" },
  { name: "super admin plans", url: `${PLAT}/plans`, as: "owner" },
  { name: "super admin audit", url: `${PLAT}/audit`, as: "owner" },
  { name: "admin billing", url: `${ADMIN}/billing` },
];

test.describe("every Phase 5 screen", () => {
  test.beforeEach(async ({ context }) => {
    await context.addCookies([{ name: "dev_user", value: "owner@rongdhonu.example", url: ADMIN }, { name: "dev_platform_user", value: "owner@biztrackbd.example", url: PLAT }]);
  });
  for (const s of SCREENS) {
    test(`${s.name} is accessible, fits the screen and has big enough tap targets`, async ({ page }, info) => {
      const res = await page.goto(s.url);
      expect(res?.status()).toBe(200);
      await expect(page.locator("main, [role=main]").first()).toBeVisible();
      const axe = await new AxeBuilder({ page }).withTags(["wcag2a", "wcag2aa", "wcag21aa"]).analyze();
      expect(axe.violations.map((v) => `${v.id}: ${v.nodes.map((x) => x.target.join(" ")).slice(0, 3).join(" | ")}`)).toEqual([]);
      expect(await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth), "page scrolls sideways").toBeLessThanOrEqual(1);
      if (info.project.name.startsWith("mobile")) {
        const small = await page.evaluate(() => {
          const bad: string[] = [];
          for (const el of document.querySelectorAll<HTMLElement>("a[href], button, input:not([type=hidden]), select, textarea, summary")) {
            const r = el.getBoundingClientRect();
            if (r.width === 0 || r.height === 0 || getComputedStyle(el).visibility === "hidden") continue;
            if (el instanceof HTMLInputElement && (el.type === "checkbox" || el.type === "radio")) continue;
            if (r.height < 40 && !el.closest(".tabs, nav.pager, p, li, .chips, .foot-links, .hp")) bad.push(`${el.tagName.toLowerCase()} "${(el.textContent || el.getAttribute("aria-label") || "").trim().slice(0, 24)}" ${Math.round(r.height)}px`);
          }
          return bad.slice(0, 6);
        });
        expect(small, "tap targets under 40px").toEqual([]);
      }
    });
  }
});

"use client";

import Link from "next/link";
import { useEffect, useMemo, useRef, useState } from "react";
import type { Quote } from "@biztrackbd/core";
import { BD_GEO } from "@biztrackbd/core/geo";
import { SubmitButton } from "@/components/ui";
import { taka } from "@/lib/format";
import {
  createDeskOrderAction, deskQuoteAction, lookupCustomerAction, parseMessageAction, searchProductsAction,
} from "./actions";

type Found = Awaited<ReturnType<typeof lookupCustomerAction>>;
type Variant = Awaited<ReturnType<typeof searchProductsAction>>[number];
interface Line { variantId: string; label: string; price: number; stock: number; quantity: number }

const SOURCES = [["MESSENGER", "Messenger"], ["WHATSAPP", "WhatsApp"], ["PHONE", "Phone call"], ["INSTAGRAM", "Instagram"]] as const;
const PAY = [["COD", "Cash on delivery"], ["MANUAL_BKASH", "Paid by bKash"], ["MANUAL_NAGAD", "Paid by Nagad"]] as const;

const digits = (raw: string) => {
  let d = raw.replace(/\D/g, "");
  if (d.startsWith("880")) d = d.slice(3);
  if (d.startsWith("0")) d = d.slice(1);
  return d.slice(0, 10);
};
const show = (d: string) => (d.length > 4 ? `${d.slice(0, 4)}-${d.slice(4)}` : d);
const uuid = () => (typeof crypto !== "undefined" && "randomUUID" in crypto ? crypto.randomUUID() : `k-${Date.now()}-${Math.random().toString(36).slice(2)}`);

export interface Prefill {
  /** The 10 digits after 0, as the phone box holds them. */
  phone: string;
  name: string;
  division: string;
  district: string;
  lines: Line[];
  /** The abandoned checkout this order will close. */
  fromAbandoned: boolean;
}

export function QuickOrderDesk({ prefill }: { prefill?: Prefill }) {
  const [key, setKey] = useState(uuid);
  const [started, setStarted] = useState(() => Date.now());
  const [tick, setTick] = useState(0);
  const [message, setMessage] = useState("");
  const [phone, setPhone] = useState(prefill?.phone ?? "");
  const [found, setFound] = useState<Found>(null);
  const [name, setName] = useState(prefill?.name ?? "");
  const [division, setDivision] = useState(prefill?.division || "Dhaka");
  const [district, setDistrict] = useState(prefill?.district || "Dhaka");
  const [upazila, setUpazila] = useState("");
  const [address, setAddress] = useState("");
  const [source, setSource] = useState<(typeof SOURCES)[number][0]>(prefill ? "PHONE" : "MESSENGER");
  const [lines, setLines] = useState<Line[]>(prefill?.lines ?? []);
  const [q, setQ] = useState("");
  const [results, setResults] = useState<Variant[]>([]);
  const [pay, setPay] = useState<(typeof PAY)[number][0]>("COD");
  const [trx, setTrx] = useState("");
  const [coupon, setCoupon] = useState("");
  const [note, setNote] = useState("");
  const [quote, setQuote] = useState<Quote | null>(null);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const [done, setDone] = useState<{ id: string; number: string; total: number }[]>([]);
  const seq = useRef(0);

  useEffect(() => { const t = setInterval(() => setTick((n) => n + 1), 1000); return () => clearInterval(t); }, []);
  const secs = Math.floor((Date.now() - started) / 1000) + 0 * tick;

  const districts = useMemo(() => BD_GEO.find((d) => d.name === division)?.districts ?? [], [division]);
  const upazilas = useMemo(() => districts.find((d) => d.name === district)?.upazilas ?? [], [districts, district]);

  // Known customer: look up as soon as a full number is typed.
  useEffect(() => {
    if (!/^1[3-9]\d{8}$/.test(phone)) { setFound(null); return; }
    let live = true;
    lookupCustomerAction(`0${phone}`).then((c) => { if (live) setFound(c); });
    return () => { live = false; };
  }, [phone]);

  // Product search.
  useEffect(() => {
    if (q.trim().length < 2) { setResults([]); return; }
    let live = true;
    const t = setTimeout(() => searchProductsAction(q).then((r) => { if (live) setResults(r); }), 200);
    return () => { live = false; clearTimeout(t); };
  }, [q]);

  // Live totals from the same rules the order uses.
  useEffect(() => {
    if (lines.length === 0) { setQuote(null); return; }
    const mine = ++seq.current;
    const t = setTimeout(async () => {
      const r = await deskQuoteAction({ items: lines.map((l) => ({ variantId: l.variantId, quantity: l.quantity })), district, paymentMethod: pay, couponCode: coupon || undefined });
      if (mine === seq.current && r.ok) setQuote(r.quote);
    }, 150);
    return () => clearTimeout(t);
  }, [lines, district, pay, coupon]);

  async function fillFromMessage() {
    if (!message.trim()) return;
    const p = await parseMessageAction(message);
    if (p.phone) setPhone(digits(p.phone));
    if (p.name) setName(p.name);
    if (p.division && p.district) { setDivision(p.division); setDistrict(p.district); }
    if (p.upazila) setUpazila(p.upazila);
    if (p.addressHint) setAddress(p.addressHint);
    if (p.payment === "MANUAL_BKASH" || p.payment === "MANUAL_NAGAD" || p.payment === "COD") setPay(p.payment);
    const first = p.items[0];
    if (first) {
      if (first.variantId) {
        const r = await searchProductsAction(first.label.split(" (")[0]!);
        const v = r.find((x) => x.variantId === first.variantId);
        if (v) addVariant(v, first.quantity);
      } else {
        setQ(first.label);
      }
    }
  }

  function addVariant(v: Variant, quantity = 1) {
    setLines((cur) => {
      const found = cur.find((l) => l.variantId === v.variantId);
      if (found) return cur.map((l) => (l.variantId === v.variantId ? { ...l, quantity: Math.min(l.quantity + quantity, Math.max(v.stock, 1)) } : l));
      return [...cur, { variantId: v.variantId, label: `${v.productTitle}${v.variantTitle.toLowerCase() === "default" ? "" : ` (${v.variantTitle})`}`, price: v.price, stock: v.stock, quantity: Math.min(quantity, Math.max(v.stock, 1)) }];
    });
    setQ("");
    setResults([]);
  }

  function reset(keepSource = true) {
    setKey(uuid()); setStarted(Date.now()); setMessage(""); setPhone(""); setFound(null); setName(""); setDivision("Dhaka"); setDistrict("Dhaka"); setUpazila("");
    setAddress(""); setLines([]); setQ(""); setPay("COD"); setTrx(""); setCoupon(""); setNote(""); setQuote(null); setError("");
    if (!keepSource) setSource("MESSENGER");
  }

  function problem(): string {
    if (!/^1[3-9]\d{8}$/.test(phone)) return "Enter the customer's mobile number.";
    if (name.trim().length < 2) return "Enter the customer's name.";
    if (!upazila) return "Choose the upazila or thana.";
    if (address.trim().length < 5) return "Enter the house, road and area.";
    if (lines.length === 0) return "Add at least one product.";
    const over = lines.find((l) => l.quantity > l.stock);
    if (over) return `Only ${over.stock} left of ${over.label}.`;
    return "";
  }

  async function create(next: boolean) {
    if (busy) return;
    const p = problem();
    setError(p);
    if (p) return;
    setBusy(true);
    const r = await createDeskOrderAction({
      idempotencyKey: key, source, customer: { name: name.trim(), phone: `0${phone}` }, shipping: { division, district, upazila, address: address.trim() },
      items: lines.map((l) => ({ variantId: l.variantId, quantity: l.quantity })), paymentMethod: pay, alreadyPaid: pay !== "COD",
      trxId: pay !== "COD" && trx.trim() ? trx.trim().toUpperCase() : undefined, couponCode: coupon.trim() || undefined, note: note.trim() || undefined,
    });
    setBusy(false);
    if (!r.ok) { setError(r.error); return; }
    setDone((d) => [{ id: r.orderId, number: r.orderNumber, total: r.total }, ...d].slice(0, 5));
    if (next) reset(true);
    else window.location.assign(`/orders/${r.orderId}`);
  }

  return (
    <div onKeyDown={(e) => { if ((e.ctrlKey || e.metaKey) && e.key === "Enter") { e.preventDefault(); void create(true); } }} data-testid="quick-desk">
      <div className="page-head">
        <h1>Quick order desk</h1>
        <div className="actions"><span className="pill grey num" aria-label="Time on this order">{Math.floor(secs / 60)}:{String(secs % 60).padStart(2, "0")}</span></div>
      </div>
      <p className="page-sub">For orders that arrive on Messenger, WhatsApp, Instagram or the phone. Aim for 15 seconds.</p>

      <div className="split">
        <div className="col stack">
          <section className="card">
            <label className="field" style={{ marginBottom: 8 }}>
              <span className="label">Paste the customer's message <span className="opt">(optional)</span></span>
              <textarea className="textarea" value={message} onChange={(e) => setMessage(e.target.value)} placeholder="Tania Akter, 01712345678, মিরপুর ১০, ব্লক সি রোড ৭ বাসা ১৪। Panjabi L, 1 pcs. COD" data-testid="desk-message" />
            </label>
            <div className="row"><button type="button" className="btn btn-secondary" onClick={fillFromMessage} data-testid="desk-fill">Fill the form</button><span className="muted" style={{ fontSize: 13 }}>We suggest the phone, name, place and product. Check each field before you save.</span></div>
          </section>

          <section className="card">
            <h2>Customer</h2>
            <label className="field">
              <span className="label">Mobile number</span>
              <div className="row" style={{ flexWrap: "nowrap", gap: 0 }}>
                <span className="input" style={{ width: "auto", display: "flex", alignItems: "center", borderRight: 0, borderRadius: "10px 0 0 10px", background: "var(--bg)", color: "var(--ink-3)" }}>+880</span>
                <input className="input" style={{ borderRadius: "0 10px 10px 0" }} inputMode="tel" autoComplete="off" placeholder="1712-345678" value={show(phone)} onChange={(e) => setPhone(digits(e.target.value))} data-testid="desk-phone" />
              </div>
            </label>
            {found && (
              <div className={`notice ${found.blocked ? "bad" : "good"}`} style={{ marginBottom: 14 }} data-testid="desk-known">
                {found.blocked ? "This number is on your blocked list. The order will be refused." : `Returning customer. ${found.orders} ${found.orders === 1 ? "order" : "orders"}, ${taka(found.spent)}${found.deliverySuccessPercent != null ? `, ${found.deliverySuccessPercent}% delivered` : ""}.`}
                {found.lastAddress && !found.blocked && (
                  <> <button type="button" className="link" style={{ border: 0, background: "none", cursor: "pointer", padding: 0 }} onClick={() => {
                    const a = found.lastAddress!;
                    if (!name) setName(found.name);
                    setDivision(a.division); setDistrict(a.district); setUpazila(a.area); setAddress(a.line);
                  }}>Use saved address</button></>
                )}
              </div>
            )}
            <label className="field"><span className="label">Name</span><input className="input" value={name} onChange={(e) => setName(e.target.value)} data-testid="desk-name" /></label>
            <div className="row-2">
              <label className="field"><span className="label">Division</span>
                <select className="select" value={division} onChange={(e) => { const v = e.target.value; setDivision(v); setDistrict(BD_GEO.find((d) => d.name === v)?.districts[0]?.name ?? ""); setUpazila(""); }}>{BD_GEO.map((d) => <option key={d.name}>{d.name}</option>)}</select>
              </label>
              <label className="field"><span className="label">District</span>
                <select className="select" value={district} onChange={(e) => { setDistrict(e.target.value); setUpazila(""); }} data-testid="desk-district">{districts.map((d) => <option key={d.name}>{d.name}</option>)}</select>
              </label>
            </div>
            <label className="field"><span className="label">Upazila or thana</span>
              <select className="select" value={upazila} onChange={(e) => setUpazila(e.target.value)} data-testid="desk-upazila"><option value="">Choose…</option>{upazilas.map((u) => <option key={u}>{u}</option>)}</select>
            </label>
            <label className="field"><span className="label">House, road and area</span><textarea className="textarea" style={{ minHeight: 64 }} value={address} onChange={(e) => setAddress(e.target.value)} data-testid="desk-address" /></label>
            <div className="field" style={{ marginBottom: 0 }}>
              <span className="label">Where did the order come from?</span>
              <div className="chips" role="group" aria-label="Order source">{SOURCES.map(([v, l]) => <button key={v} type="button" className="chip" aria-pressed={source === v} onClick={() => setSource(v)}>{l}</button>)}</div>
            </div>
          </section>
        </div>

        <div className="col stack">
          <section className="card">
            <h2>Products</h2>
            <label className="field"><span className="label">Type a name or SKU</span>
              <input className="input" value={q} onChange={(e) => setQ(e.target.value)} placeholder="Cotton Panjabi" autoComplete="off" data-testid="desk-search" />
            </label>
            {results.length > 0 && (
              <div className="stack" style={{ marginBottom: 12 }} data-testid="desk-results">
                {results.map((v) => (
                  <button key={v.variantId} type="button" className="list-card" style={{ width: "100%", textAlign: "left", cursor: v.stock > 0 ? "pointer" : "not-allowed", opacity: v.stock > 0 ? 1 : 0.5 }} disabled={v.stock <= 0} onClick={() => addVariant(v)}>
                    <div className="top"><b>{v.productTitle}{v.variantTitle.toLowerCase() !== "default" ? ` · ${v.variantTitle}` : ""}</b><span className="num">{taka(v.price)}</span></div>
                    <div className="muted" style={{ fontSize: 12.5 }}>{v.stock > 0 ? `${v.stock} in stock` : "Out of stock"}{v.sku ? ` · ${v.sku}` : ""}</div>
                  </button>
                ))}
              </div>
            )}
            {lines.length === 0 && results.length === 0 && <p className="muted">No products added yet.</p>}
            {lines.map((l) => (
              <div key={l.variantId} className="row" style={{ padding: "8px 0", flexWrap: "nowrap" }} data-testid="desk-line">
                <div style={{ flex: 1, minWidth: 0 }}><b>{l.label}</b><div className="muted num" style={{ fontSize: 13 }}>{taka(l.price)}{l.quantity > l.stock ? ` · only ${l.stock} left` : ""}</div></div>
                <div className="row" style={{ flexWrap: "nowrap", gap: 4 }}>
                  <button type="button" className="btn btn-secondary btn-sm" aria-label="Fewer" onClick={() => setLines((c) => c.flatMap((x) => (x.variantId === l.variantId ? (x.quantity > 1 ? [{ ...x, quantity: x.quantity - 1 }] : []) : [x])))}>−</button>
                  <b className="num" style={{ minWidth: 24, textAlign: "center" }}>{l.quantity}</b>
                  <button type="button" className="btn btn-secondary btn-sm" aria-label="More" disabled={l.quantity >= l.stock} onClick={() => setLines((c) => c.map((x) => (x.variantId === l.variantId ? { ...x, quantity: x.quantity + 1 } : x)))}>+</button>
                </div>
              </div>
            ))}
          </section>

          <section className="card">
            <h2>Payment</h2>
            <div className="chips" role="group" aria-label="Payment">{PAY.map(([v, l]) => <button key={v} type="button" className="chip" aria-pressed={pay === v} onClick={() => setPay(v)} data-testid={`desk-pay-${v}`}>{l}</button>)}</div>
            {pay !== "COD" && (
              <label className="field" style={{ marginTop: 12 }}><span className="label">TrxID <span className="opt">(optional, if you have it)</span></span><input className="input" value={trx} onChange={(e) => setTrx(e.target.value)} maxLength={20} /></label>
            )}
            <label className="field" style={{ marginTop: 12 }}><span className="label">Coupon <span className="opt">(optional)</span></span><input className="input" style={{ textTransform: "uppercase" }} value={coupon} onChange={(e) => setCoupon(e.target.value)} /></label>
            {quote?.couponError && <div className="err">{quote.couponError}</div>}
            <label className="field"><span className="label">Note <span className="opt">(optional)</span></span><input className="input" value={note} onChange={(e) => setNote(e.target.value)} maxLength={300} /></label>
            <div className="totals" data-testid="desk-totals">
              <div className="r"><span>Subtotal</span><span className="num">{taka(quote?.subtotal ?? 0)}</span></div>
              {quote && quote.discount > 0 && <div className="r"><span>Discount {quote.couponCode}</span><span className="num">− {taka(quote.discount)}</span></div>}
              <div className="r"><span>Delivery{quote?.zone ? `, ${quote.zone.name.toLowerCase()} (auto)` : ""}</span><span className="num">{quote?.deliveryCharge == null ? "—" : taka(quote.deliveryCharge)}</span></div>
              {quote && quote.codFee > 0 && <div className="r"><span>Cash on delivery fee</span><span className="num">{taka(quote.codFee)}</span></div>}
              <div className="r grand"><span>Total{pay === "COD" ? ", cash on delivery" : ", already paid"}</span><span className="num" data-testid="desk-total">{quote?.total == null ? taka(quote?.subtotal ?? 0) : taka(quote.total)}</span></div>
            </div>
            {error && <div className="notice bad" role="alert" style={{ marginTop: 12 }} data-testid="desk-error">{error}</div>}
            <div className="stack" style={{ marginTop: 14 }}>
              <SubmitButton className="btn btn-primary btn-block btn-lg" pending="Creating…" disabled={busy} onClick={(e) => { e.preventDefault(); void create(false); }} data-testid="desk-create">Create order</SubmitButton>
              <button type="button" className="btn btn-secondary btn-block" disabled={busy} onClick={() => void create(true)} data-testid="desk-create-next">Create and start the next one</button>
              <p className="muted" style={{ fontSize: 12.5, textAlign: "center" }}>Press Ctrl and Enter to save and start the next order.</p>
            </div>
          </section>

          {done.length > 0 && (
            <section className="card" data-testid="desk-done">
              <h2>Just created</h2>
              {done.map((d) => <div key={d.id} className="row" style={{ justifyContent: "space-between", padding: "4px 0" }}><Link href={`/orders/${d.id}`} className="link" prefetch={false}>{d.number}</Link><span className="num">{taka(d.total)}</span></div>)}
            </section>
          )}
        </div>
      </div>
    </div>
  );
}

import { randomUUID } from "node:crypto";
import { Prisma, getBasePrisma, withTenant, type TenantTx } from "@biztrackbd/db";
import { z } from "zod";
import { STORE_THEMES, validateThemeId } from "../builder/theme";
import { audit } from "../audit/service";
import { DomainError, ValidationError } from "../errors";
import { publishEvent } from "../events";
import { normalizeBdPhone } from "../phone";
import { validateSubdomain } from "../routing/host";
import { scanBrandRisk } from "./brand";

const EXTERNAL_AUTH = "EXTERNAL_AUTH";
const MAX_STORES_PER_EMAIL = 3;

/** Themes a new store can start on. Specialized behavior is enabled separately through modules. */
export const THEMES = STORE_THEMES.map(({ id, name, blurb }) => ({ id, name, blurb, live: true })) as readonly {
  id: (typeof STORE_THEMES)[number]["id"];
  name: string;
  blurb: string;
  live: true;
}[];

export const SignupInput = z.object({
  ownerName: z.string().trim().min(2, "Enter your name").max(80),
  email: z.string().trim().toLowerCase().email("Enter a valid email address").max(120),
  phone: z.string().trim().min(1, "Enter your mobile number"),
  storeName: z.string().trim().min(2, "Enter your store name").max(60),
  subdomain: z.string().trim().toLowerCase(),
  plan: z.enum(["STARTER", "PRO", "BUSINESS"]).default("PRO"),
  theme: z.enum(["kapor", "gadgetstudio", "mini-bunny", "axionwear", "bindu"]).default("kapor"),
  tagline: z.string().trim().max(120).optional(),
  locale: z.enum(["bn-BD", "en-US"]).default("bn-BD"),
  demoData: z.boolean().default(true),
});
export type SignupInput = z.input<typeof SignupInput>;

export type SubdomainCheck = { ok: true; label: string } | { ok: false; reason: "too_short" | "too_long" | "invalid" | "reserved" | "taken" };

export const SUBDOMAIN_MESSAGES: Record<string, string> = {
  too_short: "Use at least 3 letters or numbers", too_long: "Use 40 characters or fewer", invalid: "Use only letters, numbers and single hyphens",
  reserved: "That name is kept for BizTrackBD. Choose another.", taken: "That address is already taken. Try another.",
};

/** Live check for the wizard: is this address free? */
export async function checkSubdomain(input: string): Promise<SubdomainCheck> {
  const v = validateSubdomain(input);
  if (!v.ok) return v;
  const [r] = await getBasePrisma().$queryRaw<{ taken: boolean }[]>`SELECT signup_subdomain_taken(${v.label}) AS taken`;
  return r?.taken ? { ok: false, reason: "taken" } : { ok: true, label: v.label };
}

export interface SignedUp {
  tenantId: string;
  subdomain: string;
  storeName: string;
  plan: "STARTER" | "PRO" | "BUSINESS";
  trialEndsAt: Date;
  /** Waiting for a person to look at the name before a custom domain can be connected. */
  quarantined: boolean;
}

/** Three sample products so a new owner sees a working store at once. They count against the plan like any product and can be deleted. */
async function seedDemoCatalog(tx: TenantTx, tenantId: string): Promise<void> {
  const category = await tx.category.create({ data: { tenantId, name: "Sample products", slug: "sample-products" } });
  const defs = [
    { title: "Sample cotton panjabi", slug: "sample-cotton-panjabi", price: 1250, cost: 700, sizes: ["M", "L", "XL"] },
    { title: "Sample linen shirt", slug: "sample-linen-shirt", price: 950, cost: 520, sizes: ["M", "L"] },
    { title: "Sample cotton socks, 3 pack", slug: "sample-cotton-socks", price: 300, cost: 140, sizes: ["Free size"] },
  ];
  for (const d of defs) {
    const p = await tx.product.create({
      data: { tenantId, title: d.title, slug: d.slug, descriptionHtml: "<p>A sample product. Edit or delete it, then add your own.</p>", status: "ACTIVE", basePrice: d.price, costPrice: d.cost, categoryId: category.id },
    });
    for (const size of d.sizes) {
      await tx.productVariant.create({ data: { tenantId, productId: p.id, title: size, sku: `${d.slug}-${size}`.toUpperCase().replace(/\s+/g, "-"), price: d.price, stockQuantity: 20, options: { Size: size } } });
    }
  }
  await tx.$executeRaw`UPDATE "Tenant" SET "productCount" = "productCount" + ${defs.length} WHERE id = ${tenantId}`;
}

function failureOf(e: unknown): string {
  const msg = e instanceof Prisma.PrismaClientKnownRequestError ? JSON.stringify(e.meta ?? {}) + e.message : e instanceof Error ? e.message : "";
  return msg;
}

/**
 * Creates a store, its owner, its trial and its starting settings in one go (docs/16 phase 5, docs/23 onboarding).
 * The owner is created without a password: sign-in is by the platform's auth provider, which is not connected yet.
 */
export async function signupStore(raw: unknown, opts: { now?: Date } = {}): Promise<SignedUp> {
  const parsed = SignupInput.safeParse(raw);
  if (!parsed.success) throw new ValidationError(parsed.error.issues[0]?.message ?? "Check the form", { field: parsed.error.issues[0]?.path[0] });
  const input = parsed.data;
  let phone: string;
  try {
    phone = normalizeBdPhone(input.phone);
  } catch {
    throw new ValidationError("Enter a valid Bangladeshi mobile number, like 01712345678", { field: "phone" });
  }
  validateThemeId(input.theme);
  const sub = validateSubdomain(input.subdomain);
  if (!sub.ok) throw new ValidationError(SUBDOMAIN_MESSAGES[sub.reason]!, { field: "subdomain" });

  const base = getBasePrisma();
  const plan = await base.plan.findUnique({ where: { tier: input.plan } });
  if (!plan || !plan.isPublic) throw new ValidationError("Choose a plan", { field: "plan" });
  const brand = scanBrandRisk(input.storeName, sub.label);

  const id = randomUUID();
  try {
    await base.$queryRaw`SELECT signup_create_tenant(${id}, ${input.storeName}, ${sub.label}, ${input.theme}, ${input.plan}::"PlanTier", ${input.ownerName}, ${input.email}, ${phone}, ${plan.trialDays}, ${brand !== null}, ${brand ? `Name or address contains "${brand}"` : null}, ${MAX_STORES_PER_EMAIL})`;
  } catch (e) {
    const m = failureOf(e);
    if (m.includes("subdomain taken")) throw new ValidationError(SUBDOMAIN_MESSAGES.taken!, { field: "subdomain" });
    if (m.includes("too many stores")) throw new ValidationError("This email already has the most stores one person can start. Sign in to the one you have.", { field: "email" });
    throw e;
  }

  try {
    const result = await withTenant(id, async (tx) => {
      const tenant = await tx.tenant.findFirstOrThrow();
      await tx.storeSettings.create({ data: { tenantId: id, storeName: input.storeName, tagline: input.tagline || null, contactPhone: phone, email: input.email } });
      await tx.shippingZone.createMany({
        data: [
          { tenantId: id, name: "Inside Dhaka city", districts: ["Dhaka"], rate: 80, freeOverAmount: 3000, etaMinDays: 1, etaMaxDays: 2 },
          { tenantId: id, name: "Outside Dhaka", districts: ["*"], rate: 130, freeOverAmount: 5000, etaMinDays: 3, etaMaxDays: 4 },
        ],
      });
      await tx.themeInstall.create({ data: { tenantId: id, themeId: input.theme, isActive: true, pagesJson: {}, settings: {} } });
      await tx.subscription.create({
        data: { tenantId: id, planTier: input.plan, interval: "MONTHLY", status: "TRIALING", amount: 0, currentPeriodStart: tenant.trialStartsAt, currentPeriodEnd: tenant.trialEndsAt },
      });
      const owner = await tx.tenantUser.create({ data: { tenantId: id, email: input.email, name: input.ownerName, phone, role: "STORE_OWNER", passwordHash: EXTERNAL_AUTH } });
      if (input.demoData) await seedDemoCatalog(tx, id);
      await audit(tx, id, { userId: owner.id, email: owner.email }, "store.created", { plan: input.plan, theme: input.theme, demoData: input.demoData, quarantined: brand !== null });
      return { tenantId: id, subdomain: sub.label, storeName: input.storeName, plan: input.plan, trialEndsAt: tenant.trialEndsAt, quarantined: brand !== null };
    });
    await publishEvent("store/created", { tenantId: id, subdomain: sub.label, plan: input.plan });
    return result;
  } catch (e) {
    // Never leave a half-made store behind: it would hold the address and the email's quota.
    await withTenant(id, (tx) => tx.tenant.delete({ where: { id } })).catch(() => undefined);
    if (e instanceof DomainError) throw e;
    throw e;
  }
}

import { createHmac } from "node:crypto";
import { beforeEach, describe, expect, it } from "vitest";
import {
  CourierError, WebhookAuthError, clearPathaoTokens, createPathao, createRedx, createSteadfast, mapPathaoStatus, mapRedxStatus, mapSteadfastStatus,
  type AdapterContext, type BookingParcel,
} from "../src";

const parcel: BookingParcel = {
  orderNumber: "BT-10482", recipientName: "Rahat Rahman", recipientPhone: "01711223344", address: "House 12, Road 5", district: "Dhaka", area: "Dhanmondi",
  codAmount: 2420, weightGrams: 500, itemCount: 2,
};

interface Call { url: string; method: string; headers: Record<string, string>; body: any }

/** A fake courier: records each call and answers from a queue of canned replies. */
function fakeFetch(replies: (Response | ((c: Call) => Response))[]) {
  const calls: Call[] = [];
  const f = (async (url: string | URL | Request, init?: RequestInit) => {
    const call: Call = { url: String(url), method: init?.method ?? "GET", headers: Object.fromEntries(Object.entries((init?.headers ?? {}) as Record<string, string>)), body: init?.body ? JSON.parse(String(init.body)) : undefined };
    calls.push(call);
    const next = replies.shift();
    if (!next) throw new Error("unexpected call");
    return typeof next === "function" ? next(call) : next;
  }) as typeof fetch;
  return { f, calls };
}
const json = (body: unknown, status = 200) => new Response(JSON.stringify(body), { status, headers: { "Content-Type": "application/json" } });
const ctx = (f: typeof fetch, over: Partial<AdapterContext> = {}): AdapterContext => ({ secrets: {}, config: {}, mode: "LIVE", fetch: f, ...over });

